import data from './assignments.json';
import type {Draft,Entry} from '../lib/saedow';
export type HomeworkStatus='started'|'blocked'|'ready';
export type Evidence={status:HomeworkStatus;attempt:string;observation:string;next:string;answer:number|null};
export const assignmentData=data;
export const quests=data.quests;
export type Quest=typeof quests[number];
const prefix='anewgam:hw:';
export function resolveQuest(id:string):Quest {const q=quests.find(q=>q.id===id);if(!q)throw Error('That assignment is not in Steven’s current HW list.');return q;}
export function makeHomeworkDraft(id:string,value:Evidence):Draft {
 const q=resolveQuest(id);if(!['started','blocked','ready'].includes(value.status))throw Error('Choose a supported discovery state.');
 for(const key of ['attempt','observation','next'] as const)if(typeof value[key]!=='string'||value[key].length>1800)throw Error('Keep each discovery field under 1,800 characters.');
 if(!value.attempt.trim())throw Error('Write what you tried or what stopped you.');
 if(value.status==='ready'&&(!value.observation.trim()||value.answer!==q.check.answer))throw Error('Add evidence and solve the understanding check before marking ready.');
 if(value.status==='ready'&&'source_hold' in q&&q.source_hold)throw Error('The exact Frontrunner source is still unverified. Save your discovery or blocker instead of claiming this install ready.');
 if(value.status==='blocked'&&!value.next.trim())throw Error('Name the missing piece or next question so the block can be picked up.');
 const body={schema:'anewgam.hw-discovery/1',assignment:id,revision:data.revision,status:value.status,attempt:value.attempt.trim(),observation:value.observation.trim(),next:value.next.trim(),answer:value.answer,assigned_by:'Steven',review:'not-submitted',learner_report:true};
 return {kind:'quest',state:value.status==='ready'?'candidate':'explored',title:'HW · '+q.title,body:JSON.stringify(body),why:q.ability,next_proof:value.status==='ready'?'Show the evidence to Steven; no review has been recorded.':value.next.trim().slice(0,600),source:prefix+id};
}
export function homeworkState(entries:Entry[]):Record<string,{value:Evidence;entry:Entry}> {
 const result:Record<string,{value:Evidence;entry:Entry}>={};
 for(const e of entries){if(!e.source.startsWith(prefix)||e.authority!=='none'||e.scope!=='device-local')continue;try{const p=JSON.parse(e.body);const id=e.source.slice(prefix.length);resolveQuest(id);if(p.schema!=='anewgam.hw-discovery/1'||p.assignment!==id||p.revision!==data.revision||!['started','blocked','ready'].includes(p.status))continue;if(p.status==='ready'&&('source_hold' in resolveQuest(id)))continue;result[id]={value:{status:p.status,attempt:String(p.attempt??''),observation:String(p.observation??''),next:String(p.next??''),answer:Number.isInteger(p.answer)?p.answer:null},entry:e};}catch{/* unrelated/old notes are not progress */}}
 return result;
}
export function homeworkSummary(entries:Entry[]):string {const state=homeworkState(entries);return ['Aiden / Goober — HW check-in for Steven','Learner reports from this browser; not sent or teacher-approved.',...quests.map(q=>{const s=state[q.id];return '\n'+q.title+' — '+(s?s.value.status==='ready'?'ready to show':s.value.status:'not started')+(s?'\nTried: '+s.value.attempt+'\nEvidence: '+s.value.observation+'\nNext: '+s.value.next:'');})].join('\n');}
export function paperTrade(input:{quantity:number;entry:number;exit:number;fee:number;slippage:number}){
 const {quantity,entry,exit,fee,slippage}=input;if(![quantity,entry,exit,fee,slippage].every(Number.isFinite)||quantity<=0||quantity>1000||entry<=0||entry>1000000||exit<0||exit>1000000||fee<0||fee>10||slippage<0||slippage>10)throw Error('Use sensible practice values: quantity 1–1000, prices up to 1,000,000, costs 0–10%.');
 const purchase=quantity*entry*(1+slippage/100);const sale=quantity*exit*(1-slippage/100);const debit=purchase*(1+fee/100),credit=sale*(1-fee/100);return {debit,credit,net:credit-debit,returnPercent:(credit-debit)/debit*100};
}

export function displayEntryBody(entry:Entry):string {
 if(!entry.source.startsWith('anewgam:hw:'))return entry.body;
 try{const p=JSON.parse(entry.body);if(p.schema!=='anewgam.hw-discovery/1')return entry.body;return ['HW learner report · '+p.status,'Tried: '+p.attempt,'Evidence: '+p.observation,'Next puzzle: '+p.next,'Kept on this device; not submitted to Steven.'].join('\n\n');}catch{return entry.body;}
}

