/** Browser-local media recovery. File bytes never leave the browser via this module. */
export const TAKE3_URL='https://assets.grok.com/users/d04206d6-ae5b-4e6e-8788-54c1ae6a26c1/generated/9856989a-f523-40bc-a327-9fc9c3f58b93/generated_video.mp4?cache=1';
export const MEDIA_LIMIT=100*1024*1024;
export type LocalVideo={blob:Blob;name:string;sha256:string;bytes:number;saved_at:string;relationship:'user-selected-local-copy-not-original-verified'};
function open():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{const r=indexedDB.open('anewgam-media-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('media');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Local video storage is unavailable.'));r.onblocked=()=>reject(Error('Close older Anewgam tabs and try again.'));});}
export async function checkMp4(file:Blob,name:string):Promise<void>{
 if(!name.toLowerCase().endsWith('.mp4')||file.size<12||file.size>MEDIA_LIMIT)throw Error('Choose a real .mp4 file no larger than 100 MiB.');
 const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());
 if(String.fromCharCode(...bytes.slice(4,8))!=='ftyp')throw Error('This file does not have a supported MP4 file header. Nothing was replaced.');
}
export async function getVideo():Promise<LocalVideo|undefined>{const db=await open();try{return await new Promise((resolve,reject)=>{const r=db.transaction('media').objectStore('media').get('take3');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}finally{db.close();}}
export async function putVideo(value:LocalVideo):Promise<void>{const db=await open();try{await new Promise<void>((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').put(value,'take3');tx.oncomplete=()=>resolve();tx.onabort=tx.onerror=()=>reject(Error('The browser could not keep this video. Check available storage; your previous copy was not deliberately removed.'));});}finally{db.close();}}
export async function forgetVideo():Promise<void>{const db=await open();try{await new Promise<void>((resolve,reject)=>{const tx=db.transaction('media','readwrite');tx.objectStore('media').delete('take3');tx.oncomplete=()=>resolve();tx.onerror=tx.onabort=()=>reject(Error('Could not remove the local copy.'));});}finally{db.close();}}

