/** SaeDow v0.1: device-local continuity. No authority, dispatch, or remote acceptance. */
export type Kind = 'note' | 'idea' | 'quest' | 'request' | 'practice';
export type State = 'imagined' | 'explored' | 'candidate' | 'completed' | 'superseded';
export type Entry = { id:string; created_at:string; kind:Kind; state:State; title:string; body:string; why:string; next_proof:string; source:string; scope:'device-local'; authority:'none'; acceptance:'self-reported'; previous:string; hash:string };
export type Draft = Pick<Entry,'kind'|'state'|'title'|'body'|'why'|'next_proof'|'source'>;
export const VERSION = 'saedow/0.1';
const DB = 'anewgam-goober-v1';
export const ROOT = '0'.repeat(64);
export function canonical(value:unknown):string {
  if (Array.isArray(value)) return '['+value.map(canonical).join(',')+']';
  if (value !== null && typeof value === 'object') return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonical((value as Record<string,unknown>)[k])).join(',')+'}';
  return JSON.stringify(value);
}
export async function digest(value:string|ArrayBuffer):Promise<string> {
 const bytes=typeof value==='string'?new TextEncoder().encode(value):value;
 return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(x=>x.toString(16).padStart(2,'0')).join('');
}
export function validateDraft(d:unknown):Draft {
 if (!d || typeof d!=='object') throw Error('This entry is not an object.');
 const x=d as Record<string,unknown>;
 for (const key of ['title','body','why','next_proof','source']) if(typeof x[key]!=='string'||(x[key] as string).length>(key==='body'?8000:600)) throw Error('Entry fields must be text within the size limit.');
 if(!(x.title as string).trim()||!['note','idea','quest','request','practice'].includes(String(x.kind))||!['imagined','explored','candidate','completed','superseded'].includes(String(x.state))) throw Error('Choose a title, entry type, and supported state.');
 return {kind:x.kind as Kind,state:x.state as State,title:(x.title as string).trim(),body:x.body as string,why:x.why as string,next_proof:x.next_proof as string,source:x.source as string};
}
export async function makeEntry(draft:Draft, previous=ROOT):Promise<Entry> {
 const clean=validateDraft(draft);
 const unsigned={...clean,id:crypto.randomUUID(),created_at:new Date().toISOString(),scope:'device-local' as const,authority:'none' as const,acceptance:'self-reported' as const,previous};
 return {...unsigned,hash:await digest(canonical(unsigned))};
}
export async function verify(entries:unknown):Promise<Entry[]> {
 if(!Array.isArray(entries)||entries.length>1000) throw Error('A log must contain at most 1,000 entries.');
 let previous=ROOT; const ids=new Set<string>();
 for(const entry of entries){
  validateDraft(entry);
  if(typeof entry.id!=='string'||entry.id.length>100||ids.has(entry.id)||typeof entry.created_at!=='string'||!Number.isFinite(Date.parse(entry.created_at))||entry.scope!=='device-local'||entry.authority!=='none'||entry.acceptance!=='self-reported'||entry.previous!==previous||typeof entry.hash!=='string') throw Error('Entry identity, scope, or chain is invalid.');
  const {hash,...unsigned}=entry;
  if(hash!==await digest(canonical(unsigned))) throw Error('An entry has changed. Import stopped without replacing your log.');
  ids.add(entry.id); previous=hash;
 }
 return entries as Entry[];
}
function open():Promise<IDBDatabase>{return new Promise((resolve,reject)=>{
 const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore('log');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('Browser storage is unavailable. Nothing was saved.'));r.onblocked=()=>reject(Error('Close older Anewgam tabs, then retry.'));
});}
export async function load():Promise<Entry[]> {
 const db=await open();try{return await new Promise((resolve,reject)=>{const r=db.transaction('log').objectStore('log').get('entries');r.onsuccess=()=>resolve(r.result??[]);r.onerror=()=>reject(r.error);});}finally{db.close();}
}
async function replace(next:Entry[],expected:string):Promise<void>{
 const db=await open();try{await new Promise<void>((resolve,reject)=>{
 const tx=db.transaction('log','readwrite'),store=tx.objectStore('log');let message='Could not save. Your previous log is unchanged.';
 const read=store.get('entries');read.onsuccess=()=>{const current:Entry[]=read.result??[];if((current.at(-1)?.hash??ROOT)!==expected){message='Another tab updated your log. Reload and try again.';tx.abort();return;}store.put(next,'entries');};
 tx.oncomplete=()=>resolve();tx.onerror=()=>reject(Error(message));tx.onabort=()=>reject(Error(message));
 });}finally{db.close();}
}
export async function append(draft:Draft):Promise<Entry[]> {
 const current=await verify(await load());if(current.length>=1000)throw Error('Export your log before starting a fresh one.');
 const head=current.at(-1)?.hash??ROOT,next=[...current,await makeEntry(draft,head)];await replace(next,head);return next;
}
export async function importLog(text:string):Promise<Entry[]>{
 if(text.length>12_000_000)throw Error('Import is too large.');const packet=JSON.parse(text);
 if(packet.schema!==VERSION)throw Error('Unsupported SaeDow format.');
 const entries=await verify(packet.entries),current=await load();
 if(current.length)throw Error('Import is allowed only into an empty log. Export your current log first; nothing was replaced.');
 await replace(entries,ROOT);return entries;
}
export async function clear(expected:string):Promise<void>{await replace([],expected);}
export function download(name:string, data:unknown){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function envelope(entries:Entry[]){return {schema:VERSION,exported_at:new Date().toISOString(),scope:'device-local',identity:'not-enrolled',skein_acceptance:'not-submitted',entries};}

