export const roles=[
 {id:'outrider',name:'Outrider',line:'Find the line nobody else sees.',detail:'Momentum, timing, and a way through. Read the space; commit to the opening.',symbol:'↗'},
 {id:'artificer',name:'Artificer',line:'Make something that changes the run.',detail:'Salvage, build, improvise. A good tool is a new possibility.',symbol:'⌘'},
 {id:'wayfinder',name:'Wayfinder',line:'Bring the crew through.',detail:'Notice the route, keep your bearings, leave a light for the next person.',symbol:'✧'}
] as const;
export type Approach = typeof roles[number]['id'];
export function validApproach(value:string):value is Approach{return roles.some(r=>r.id===value);}
export function chapter(stage:number,role:Approach){
 if(stage===0)return {title:'A light beyond the ruins.',text:'The Crossing has gone quiet. Across the broken causeway, a lantern still burns. A relay core lies beside your boots. It needs to reach the garden before the last bridge folds.',image:'crossing',action:'Take the relay',result:'You picked up the relay core. One light, three possible ways through.'};
 if(stage===1)return {title:'Your kind of impossible.',text:role==='outrider'?'The stone platforms move in a slow rhythm. You watch one full cycle, spot the open line, and keep your momentum.':role==='artificer'?'A broken rail, a coil of wire, a pulse inside the core. You do not need a perfect bridge. You need one that holds for this crossing.':'Through the mist, three lanterns blink in sequence. The brightest route is a decoy. You mark the quiet path and leave a signal for whoever follows.',image:'crossing',action:role==='outrider'?'Take the clean line':role==='artificer'?'Build the crossing':'Follow the quiet lights',result:role==='outrider'?'You crossed by reading the rhythm. A clean line opened through the ruins.':role==='artificer'?'You built a temporary crossing from what was left behind.':'You mapped the quiet route and left a light for the next traveler.'};
 return {title:'The garden remembers.',text:'The relay settles into its cradle. Water catches the lantern light. A route once thought lost is open again. This is not the end of your run. It is somewhere worth returning to.',image:'garden',action:'Keep this chapter',result:'The relay reached Garden Central. A new crossing is open in this device-local story.'};
}

