import {useEffect,useRef,useState} from 'react';
export function BoostRun({onComplete}:{onComplete:(score:number)=>Promise<void>}){
 const canvas=useRef<HTMLCanvasElement>(null);const keys=useRef(new Set<string>());const [status,setStatus]=useState<'ready'|'running'|'paused'|'finished'>('ready');const [score,setScore]=useState(0);const [seconds,setSeconds]=useState(45);const [attempt,setAttempt]=useState(0);const active=useRef(false);const completed=useRef(false);
 useEffect(()=>{const c=canvas.current;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;let id=0,last=0,elapsed=0,x=180,y=230,vx=0,vy=0,points=0;let target={x:480,y:220};const trail:{x:number,y:number}[]=[];let paused=false;active.current=attempt>0;if(attempt>0)c.focus();
 const draw=()=>{ctx.fillStyle='#101d25';ctx.fillRect(0,0,720,420);ctx.strokeStyle='#24343a';ctx.lineWidth=1;for(let i=0;i<720;i+=40){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i,420);ctx.stroke();}for(let j=0;j<420;j+=40){ctx.beginPath();ctx.moveTo(0,j);ctx.lineTo(720,j);ctx.stroke();}ctx.strokeStyle='#718e80';ctx.lineWidth=3;ctx.strokeRect(18,18,684,384);trail.forEach((p,i)=>{ctx.fillStyle=`rgba(217,197,143,${i/trail.length*.32})`;ctx.beginPath();ctx.arc(p.x,p.y,3,0,7);ctx.fill();});ctx.strokeStyle='#d9c58f';ctx.lineWidth=3;ctx.beginPath();ctx.arc(target.x,target.y,20,0,7);ctx.stroke();ctx.beginPath();ctx.arc(target.x,target.y,5,0,7);ctx.stroke();ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(vy,vx));ctx.fillStyle='#e9eee8';ctx.beginPath();ctx.moveTo(17,0);ctx.lineTo(-12,-10);ctx.lineTo(-6,0);ctx.lineTo(-12,10);ctx.closePath();ctx.fill();ctx.restore();};
 const tick=(now:number)=>{const elapsedStep=last?Math.max(0,(now-last)/1000):0;const dt=Math.min(elapsedStep,.05);last=now;if(active.current&&!paused){elapsed+=elapsedStep;let ax=0,ay=0;if(keys.current.has('ArrowLeft')||keys.current.has('a'))ax--;if(keys.current.has('ArrowRight')||keys.current.has('d'))ax++;if(keys.current.has('ArrowUp')||keys.current.has('w'))ay--;if(keys.current.has('ArrowDown')||keys.current.has('s'))ay++;const boost=keys.current.has(' ')?1.8:1;const length=Math.hypot(ax,ay)||1;vx+=(ax/length)*390*boost*dt;vy+=(ay/length)*390*boost*dt;const drag=Math.pow(keys.current.has('Shift')?.12:.42,dt);vx*=drag;vy*=drag;x+=vx*dt;y+=vy*dt;if(x<30||x>690){vx*=-.65;x=Math.max(30,Math.min(690,x));}if(y<30||y>390){vy*=-.65;y=Math.max(30,Math.min(390,y));}trail.push({x,y});if(trail.length>32)trail.shift();if(Math.hypot(x-target.x,y-target.y)<27){points++;setScore(points);target={x:60+Math.random()*600,y:60+Math.random()*300};}setSeconds(Math.max(0,Math.ceil(45-elapsed)));if(elapsed>=45&&!completed.current){completed.current=true;active.current=false;setStatus('finished');void onComplete(points);}}draw();id=requestAnimationFrame(tick);};
 const keydown=(e:KeyboardEvent)=>{if(!active.current)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d',' ','Shift'].includes(e.key)){e.preventDefault();keys.current.add(e.key);}};const keyup=(e:KeyboardEvent)=>keys.current.delete(e.key);const hide=()=>{keys.current.clear();if(document.hidden&&active.current){paused=true;setStatus('paused');}else if(!document.hidden&&active.current){paused=false;last=performance.now();setStatus('running');}};const blur=()=>keys.current.clear();document.addEventListener('keydown',keydown);document.addEventListener('keyup',keyup);document.addEventListener('visibilitychange',hide);window.addEventListener('blur',blur);id=requestAnimationFrame(tick);return()=>{cancelAnimationFrame(id);active.current=false;keys.current.clear();document.removeEventListener('keydown',keydown);document.removeEventListener('keyup',keyup);document.removeEventListener('visibilitychange',hide);window.removeEventListener('blur',blur);};
 },[attempt]);
 const start=()=>{keys.current.clear();completed.current=false;setScore(0);setSeconds(45);setAttempt(a=>a+1);setStatus('running');};
 const control=(label:string,key:string)=> <button type="button" aria-label={label} onPointerDown={e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);keys.current.add(key);}} onPointerUp={()=>keys.current.delete(key)} onPointerCancel={()=>keys.current.delete(key)} onLostPointerCapture={()=>keys.current.delete(key)}>{label}</button>;
 return <section className="boost"><div className="boost-hud"><span>SIGNAL RUN / 45 SEC</span><b>{score} signals</b><span>{seconds}s</span></div><canvas ref={canvas} width="720" height="420" tabIndex={0} aria-label="Top-down movement challenge. Steer with arrow keys or WASD, hold Space for boost and Shift to brake. Collect gold rings."/><div className="boost-under"><p>{status==='finished'?`${score} signals recovered. Your route stays open.`:status==='paused'?'Paused while this tab is hidden.':'Collect the gold signals. Momentum matters.'}</p>{(status==='ready'||status==='finished')&&<button className="primary" onClick={start}>{status==='ready'?'Start 45-second run':'Run it back'} <span>↗</span></button>}</div><div className="touch-controls">{control('←','ArrowLeft')}{control('↑','ArrowUp')}{control('↓','ArrowDown')}{control('→','ArrowRight')}{control('Boost',' ')}{control('Brake','Shift')}</div><p className="small">WASD / arrows to steer · Space to boost · Shift to brake. Touch controls above. A local skill toy, not Rocket League training or a competitive leaderboard.</p></section>;
}

