import {useEffect,useRef,type ReactNode} from 'react';
export function Dialog({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){const ref=useRef<HTMLDialogElement>(null);useEffect(()=>{const d=ref.current;d?.showModal();return()=>d?.close();},[]);return <dialog ref={ref} onCancel={onClose} onClick={e=>{if(e.target===e.currentTarget)onClose();}}><div className="dialog-inner"><div className="dialog-heading"><h2>{title}</h2><button aria-label="Close dialog" onClick={onClose}>×</button></div>{children}</div></dialog>;}
export function InfoDialog({kind,onClose}:{kind:string;onClose:()=>void}){
 if(kind==='install')return <Dialog title="Take the outpost with you." onClose={onClose}><div className="install-content"><img src="/assets/icon-192.png" alt="Anewgam app icon"/><p>One small doorway on your desktop or Home Screen.</p><h3>Windows / Microsoft Edge</h3><p>Open this site in Edge. Click the app-install icon in the address bar, then Install. You can pin the app to Start or the taskbar.</p><h3>iPhone / Safari</h3><p>Open this site in Safari. Tap Share (or More → Share), choose Add to Home Screen, turn on Open as Web App when offered, then Add.</p><p className="small">Installation is your choice. It does not grant device control, link Steam, sign in to an email account, connect a Roku, or sync your notes. Each device starts with its own local records.</p><div className="install-docs"><a href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noopener noreferrer">Apple’s instructions ↗</a><a href="https://learn.microsoft.com/en-us/microsoft-edge/progressive-web-apps/ux" target="_blank" rel="noopener noreferrer">Microsoft’s instructions ↗</a></div><a className="text-link" href="/relay.json" target="_blank" rel="noopener noreferrer">Public continuation capsule ↗</a></div></Dialog>;
 if(kind==='privacy')return <Dialog title="Local-first, honestly." onClose={onClose}><div className="privacy"><h3>What works now</h3><p>Story choices, Signal Run, role changes, your field log, corrections, archive, and JSON capsules. They persist in this browser’s IndexedDB. Tabs on the same browser profile share updates.</p><h3>What isn’t connected</h3><p>There is no account login, cross-device sync, live Sae conversation, Steam integration, Roku control, or remote worker connection in this release. A kept idea does not launch work.</p><h3>Your notes are not a vault</h3><p>Notes are not sent to an app database. They are not encrypted, and anyone using this browser profile can read them. Clearing site data removes them. Export before changing devices or clearing storage. The hosting provider still serves this site and may keep normal access logs.</p><h3>One world, no invented authority</h3><p>This is a local playtest strand. It does not write to Skein or claim that its events happened in the shared Anewgam world. Future enrollment must explicitly connect identity, consent, and sync. Roles are story choices, never permissions.</p><p className="small">Prototype 0.1 · 11 September 2026</p></div></Dialog>;
 if(kind==='art')return <Dialog title="From the existing Anewgam archive" onClose={onClose}><div className="art-view"><img src="/assets/garden.webp" alt="EverDelve: Garden Central, the existing tower-world artwork"/><p>EverDelve: Garden Central</p><img src="/assets/sanctuary.webp" alt="Enchanted Tower Garden Sanctuary, existing generated artwork"/><p>Enchanted Tower Garden Sanctuary</p><p className="small">Reused from Steven’s generated-image Library. The outpost hero is a crop of Garden Central. These images are world inspiration, not portraits of Goober.</p></div></Dialog>;
 return null;
}

