import {useEffect,useRef,useState} from 'react';
import type {ChangeEvent} from 'react';
import {TAKE3_URL,checkMp4,getVideo,putVideo,forgetVideo} from '../lib/local-media';
import type {LocalVideo} from '../lib/local-media';
import {digest} from '../lib/saedow';
export function TakeThree(){
 const player=useRef<HTMLVideoElement>(null),fileInput=useRef<HTMLInputElement>(null),objectUrl=useRef<string|undefined>(undefined),timer=useRef<ReturnType<typeof setTimeout>|undefined>(undefined);
 const [local,setLocal]=useState<LocalVideo>(),[src,setSrc]=useState(''),[status,setStatus]=useState('The source server refused our retrieval. No hosted copy has been claimed.'),[busy,setBusy]=useState(false),[ready,setReady]=useState(false);
 function useLocal(video:LocalVideo){if(objectUrl.current)URL.revokeObjectURL(objectUrl.current);objectUrl.current=URL.createObjectURL(video.blob);setLocal(video);setSrc(objectUrl.current);setReady(false);}
 useEffect(()=>{let alive=true;getVideo().then(v=>{if(alive&&v){useLocal(v);setStatus('Your saved local copy is ready to open.');}}).catch(()=>{if(alive)setStatus('Browser storage is unavailable. You can still open the original link.');});return()=>{alive=false;if(objectUrl.current)URL.revokeObjectURL(objectUrl.current);if(timer.current)clearTimeout(timer.current);};},[]);
 useEffect(()=>{if(!src)return;player.current?.load();},[src]);
 function tryOriginal(){setReady(false);setSrc(TAKE3_URL);setStatus('Trying Grok in this browser. This contacts the source host.');if(timer.current)clearTimeout(timer.current);timer.current=setTimeout(()=>{if((player.current?.readyState??0)<2)setStatus('No playable data arrived. Open the original in your browser, or choose a saved MP4 below.');},15000);}
 function loaded(){if(timer.current)clearTimeout(timer.current);setReady(true);setStatus(src.startsWith('blob:')?'Local MP4 loaded. Press play; no file upload occurs.':'The original video loaded in this browser. Press play.');}
 async function choose(e:ChangeEvent<HTMLInputElement>){const file=e.currentTarget.files?.[0];e.currentTarget.value='';if(!file)return;setBusy(true);try{
  await checkMp4(file,file.name);
  // Decode metadata before persisting an unsupported/corrupt clip over a saved one.
  const url=URL.createObjectURL(file);try{await new Promise<void>((resolve,reject)=>{const v=document.createElement('video');let timeout:ReturnType<typeof setTimeout>;const done=(error?:Error)=>{clearTimeout(timeout);v.removeAttribute('src');v.load();error?reject(error):resolve();};v.preload='metadata';v.onloadedmetadata=()=>done(Number.isFinite(v.duration)&&v.duration>0?undefined:Error('No valid video duration was found.'));v.onerror=()=>done(Error('This browser cannot decode that MP4. Your previous copy is unchanged.'));timeout=setTimeout(()=>done(Error('The MP4 could not be checked in time.')),10000);v.src=url;});}finally{URL.revokeObjectURL(url);}
  const value:LocalVideo={blob:new Blob([file],{type:'video/mp4'}),name:file.name,sha256:await digest(await file.arrayBuffer()),bytes:file.size,saved_at:new Date().toISOString(),relationship:'user-selected-local-copy-not-original-verified'};
  await putVideo(value);useLocal(value);setStatus('Saved in this browser only. This file has not been proven identical to the blocked Grok asset.');
 }catch(error){setStatus(error instanceof Error?error.message:'Could not open this file.');}finally{setBusy(false);}}
 async function forget(){if(!confirm('Remove the saved video from this browser? The original Grok link is unchanged.'))return;try{await forgetVideo();if(objectUrl.current){URL.revokeObjectURL(objectUrl.current);objectUrl.current=undefined;}setSrc('');setLocal(undefined);setReady(false);setStatus('Local copy removed.');}catch(error){setStatus(String(error));}}
 async function copy(){try{await navigator.clipboard.writeText(TAKE3_URL);setStatus('Original URL copied.');}catch{setStatus('Clipboard unavailable. Use the visible Original video link below.');}}
 return <section className="take-three" aria-labelledby="take-three-title"><div className="section-heading"><div><span className="eyebrow">SAE-KIRBY · TAKE 3</span><h2 id="take-three-title">Carry the scene forward.</h2></div><a href="/receipts/take3-video.json">Source receipt ◇</a></div>
 <div className="take-three-grid"><div className="take-three-frame">{src?<video ref={player} src={src} controls playsInline preload="metadata" poster="/assets/crossing.webp" onLoadedMetadata={loaded} onError={()=>{if(timer.current)clearTimeout(timer.current);setReady(false);setStatus('This source could not play here. Use the original link or choose a saved MP4.');}} aria-label="Take 3 video player"/>:<div className="video-poster"><img src="/assets/crossing.webp" alt="Existing Crossing art, used as a placeholder; not a frame from the unrecovered video"/><span>THE VIDEO HAS NOT BEEN RECOVERED</span></div>}</div>
 <div className="take-three-copy"><p>This scene arrived as a Grok link. The picture beside it is existing Crossing art, not a preview of that clip.</p><div className="media-actions"><button onClick={tryOriginal} disabled={busy}>Try the original player ▷</button><a href={TAKE3_URL} target="_blank" rel="noopener noreferrer">Open original video ↗</a><button onClick={copy}>Copy original URL</button><button onClick={()=>fileInput.current?.click()} disabled={busy}>{busy?'Checking file…':'Choose a saved MP4'}</button>{local&&<button onClick={()=>{useLocal(local);setStatus('Using your browser-local copy.');}}>Use saved copy</button>}</div><input ref={fileInput} hidden type="file" accept="video/mp4,.mp4" onChange={choose}/><p className="media-status" role="status">{status}</p><small>No autoplay. No hidden proxy or sign-in bypass. A browser-local copy stays on this device; it is not uploaded or synchronized.</small>
 {local&&<details><summary>Local-copy receipt {ready?'· player ready':''}</summary><p>{local.name} · {Math.round(local.bytes/1024)} KiB</p><code>{local.sha256}</code><p>Selected locally; original-source identity unverified. Saved {local.saved_at}.</p><button className="text-action" onClick={forget}>Remove local copy</button></details>}</div></div></section>;
}

