import {useEffect,useMemo,useRef,useState} from 'react';
import type {Draft,Entry} from '../lib/saedow';
import {assignmentData,quests,resolveQuest,makeHomeworkDraft,homeworkState,homeworkSummary,paperTrade} from './hw-core';
import type {Quest,Evidence,HomeworkStatus} from './hw-core';
const empty:Evidence={status:'started',attempt:'',observation:'',next:'',answer:null};
const stateLabel={started:'In discovery',blocked:'Needs a clue',ready:'Ready to show Steven'};
function selectedId(){try{return window.location.hash.startsWith('#hw/')?decodeURIComponent(window.location.hash.slice(4)):'';}catch{return '!invalid';}}
function PaperLab({useEvidence}:{useEvidence:(text:string)=>void}){
 const [values,setValues]=useState({quantity:10,entry:100,exit:102,fee:1,slippage:0}),[result,setResult]=useState<ReturnType<typeof paperTrade>|null>(null),[error,setError]=useState('');
 const labels={quantity:'Units',entry:'Entry price ($)',exit:'Exit price ($)',fee:'Fee each side (%)',slippage:'Slippage each side (%)'};
 const dollars=(n:number)=>n.toLocaleString('en-US',{style:'currency',currency:'USD'});
 return <section className="hw-lab" aria-labelledby="paper-title"><span className="hw-kicker">PRACTICE / NO REAL ORDERS</span><h3 id="paper-title">Price up. Profit… maybe?</h3><p>Invented numbers. Predict the result before pressing reveal.</p><div className="hw-paper-fields">{(Object.keys(labels) as Array<keyof typeof values>).map(key=><label key={key}>{labels[key]}<input type="number" min={key==='quantity'?1:0} max={key==='quantity'?1000:key==='fee'||key==='slippage'?10:1000000} step="any" value={Number.isNaN(values[key])?'':values[key]} onChange={e=>{setValues({...values,[key]:e.target.value===''?NaN:Number(e.target.value)});setResult(null);setError('');}}/></label>)}</div><button type="button" className="hw-action secondary" onClick={()=>{try{setResult(paperTrade(values));setError('');}catch(e){setError(e instanceof Error?e.message:'Check your numbers.');}}}>Reveal the paper result</button>{error&&<p role="alert">{error}</p>}{result&&<div className="hw-paper-result" role="status"><span>Total entry cost <b>{dollars(result.debit)}</b></span><span>Exit after fees <b>{dollars(result.credit)}</b></span><span>Net result <b>{dollars(result.net)}</b></span><button type="button" className="hw-text-action" onClick={()=>useEvidence(`Paper test only: ${values.quantity} units, entry $${values.entry}, exit $${values.exit}, fees ${values.fee}% per side, slippage ${values.slippage}% per side. Cost ${dollars(result.debit)}, proceeds ${dollars(result.credit)}, net ${dollars(result.net)}.`)}>Add this result to my evidence ↓</button></div>}<small>No live price, wallet, balance, trade or investment recommendation is connected.</small></section>;
}
export function Homework({entries,onKeep,ready}:{entries:Entry[];onKeep:(draft:Draft)=>Promise<boolean|undefined>;ready:boolean}){
 const [id,setId]=useState(selectedId),[filter,setFilter]=useState('all'),[evidence,setEvidence]=useState<Evidence>(empty),[dirty,setDirty]=useState(false),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[feedback,setFeedback]=useState('');
 const detailRef=useRef<HTMLElement>(null);const initialized=useRef<string|null>(null);const progress=useMemo(()=>homeworkState(entries),[entries]);const readyCount=Object.values(progress).filter(x=>x.value.status==='ready').length;
 let quest:Quest|undefined;try{if(id)quest=resolveQuest(id);}catch{/* do not substitute another task */}
 useEffect(()=>{const change=()=>{setId(selectedId());setDirty(false);setNotice('');setFeedback('');};window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change);},[]);
 useEffect(()=>{if(!ready||initialized.current===id)return;const prior=progress[id]?.value;setEvidence(prior?{...prior}:empty);setFeedback('');setDirty(false);initialized.current=id;},[id,ready,progress]);
 useEffect(()=>{if(!dirty)return;const leaving=(e:BeforeUnloadEvent)=>{e.preventDefault();e.returnValue='';};const click=(e:MouseEvent)=>{const link=(e.target as Element)?.closest?.('a');if(link&&link.target!=='_blank'&&link.getAttribute('href')?.startsWith('#')&&link.getAttribute('href')!==window.location.hash&&!window.confirm('Leave this unsaved discovery? Save it first to keep your notes.')){e.preventDefault();e.stopPropagation();}};window.addEventListener('beforeunload',leaving);document.addEventListener('click',click,true);return()=>{window.removeEventListener('beforeunload',leaving);document.removeEventListener('click',click,true);};},[dirty]);
 function choose(next:string){if(dirty&&!window.confirm('Leave the unsaved discovery and open another assignment?'))return;setDirty(false);if(id===next)return;window.location.hash='hw/'+next;setTimeout(()=>detailRef.current?.scrollIntoView({block:'start',behavior:'auto'}),50);}
 function update(patch:Partial<Evidence>){setEvidence(v=>({...v,...patch}));setDirty(true);setNotice('');}
 async function keep(status:HomeworkStatus){if(!quest||busy||!ready)return;let draft:Draft;try{draft=makeHomeworkDraft(quest.id,{...evidence,status});}catch(e){setNotice(e instanceof Error?e.message:'Check this discovery first.');return;}setBusy(true);try{if(await onKeep(draft)){setEvidence(v=>({...v,status}));setDirty(false);setNotice(status==='ready'?'Evidence prepared. Kept on this device—not sent to Steven or approved yet.':status==='blocked'?'The blocker and next question are kept. A stuck step is still useful progress.':'Discovery saved in your existing field log.');}}finally{setBusy(false);}}
 async function copySummary(){try{await navigator.clipboard.writeText(homeworkSummary(entries));setNotice('Check-in copied. Review it before sharing with Steven; nothing was sent.');}catch{setNotice('Clipboard unavailable. Your saved discoveries remain in the field log.');}}
 const zones=[...new Set(quests.map(q=>q.zone))];const shown=quests.filter(q=>filter==='all'||q.zone===filter);
 return <section className="hw" aria-labelledby="hw-title"><div className="hw-hero"><img src="/goober/assets/rediscovered/peachfall-02.webp" alt="A luminous constellation from the existing Anewgam artwork"/><div className="hw-hero-veil"/><div className="hw-hero-copy"><span className="hw-kicker">HW · ASSIGNMENTS FROM STEVEN</span><h1 id="hw-title">Build your<br/><em>next ability.</em></h1><p>Aiden, turn a little curiosity into something you can actually do. Try one small thing. Show what changed. Leave the next puzzle.</p><a href="#hw/ai-prep" className="hw-start">Start at the launch pad <span>↗</span></a></div><div className="hw-hero-stat"><strong>{readyCount}<small> / {quests.length}</small></strong><span>evidence sets ready to show<br/>not teacher-approved completions</span></div></div>
 <div className="hw-loop"><span>PDD · DISCOVERY MODE</span><p><b>Puzzle</b> → Try → Observe → Evidence → <b>Next puzzle</b></p><small>Hints are allowed. “I’m stuck here” is a useful discovery.</small></div>
 <div className="hw-section-head"><div><span className="hw-kicker">YOUR CURRENT ASSIGNMENTS</span><h2>A loadout for making things.</h2></div><button type="button" className="hw-text-action" onClick={copySummary} disabled={!ready}>Copy check-in for Steven ↗</button></div>
 <nav className="hw-filters" aria-label="Homework topics"><button type="button" aria-pressed={filter==='all'} onClick={()=>setFilter('all')}>All HW</button>{zones.map(zone=><button type="button" key={zone} aria-pressed={filter===zone} onClick={()=>setFilter(zone)}>{zone}</button>)}</nav>
 <div className="hw-cards">{shown.map(q=><button type="button" className={'hw-card '+(q.id===id?'selected':'')} key={q.id} onClick={()=>choose(q.id)} aria-pressed={q.id===id}><span className="hw-card-top"><span>{q.zone}</span><span>~{q.minutes} min</span></span><strong>{q.title}</strong><span className="hw-card-ability">{q.ability}</span><span className="hw-card-bottom"><span>{q.device}</span><b>{progress[q.id]?stateLabel[progress[q.id].value.status]:'source_hold' in q?'Verify source first':'Not started'} →</b></span></button>)}</div>
 {id&&!quest&&<div className="hw-note" role="alert">That assignment is not in Steven’s current list. <a href="#hw">Return to HW</a>; no other assignment was substituted.</div>}
 {quest&&<section className="hw-detail" ref={detailRef} aria-labelledby="quest-title" key={quest.id}><div className="hw-detail-banner"><div><span className="hw-kicker">{quest.zone.toUpperCase()} / {quest.device}</span><h2 id="quest-title">{quest.title}</h2><p>{quest.puzzle}</p></div><span className="hw-state">{progress[id]?stateLabel[progress[id].value.status]:'Open puzzle'}</span></div>
 {'caution' in quest&&quest.caution&&<p className="hw-caution">{quest.caution}</p>}
 <div className="hw-detail-columns"><div><h3>Try the smallest useful version.</h3><ol className="hw-steps">{quest.steps.map((step,i)=><li key={i}><span>{String(i+1).padStart(2,'0')}</span><p>{step}</p></li>)}</ol>
 <div className="hw-links">{quest.links.map((link,i)=><a key={i} href={link.url} target={link.url.startsWith('https://')||link.url.includes('signal-lab')?'_blank':undefined} rel="noopener noreferrer" download={link.label==='Save the starter HTML'?'signal-lab.html':undefined}>{link.label} ↗</a>)}</div>
 {'command' in quest&&quest.command&&<details className="hw-hint"><summary>Command card · run only in the right place</summary><p>This page does not execute commands. Read the official guide and review the effect before using your own terminal.</p><pre>{quest.command}</pre></details>}
 <h3 className="hw-hints-title">Need a clue?</h3>{quest.hints.map((hint,i)=><details className="hw-hint" key={i}><summary>Clue {i+1} {i===1?'· more direct':''}</summary><p>{hint}</p></details>)}
 {'lab' in quest&&quest.lab==='paper'&&<PaperLab useEvidence={text=>update({observation:(evidence.observation?evidence.observation+'\n':'')+text})}/>}
 <div className="hw-proof"><span className="hw-kicker">SHOW, DON’T JUST TICK</span><h3>Evidence to bring back</h3><p>{quest.proof}</p></div>
 <details className="hw-hint hw-sources"><summary>Official sources · checked {assignmentData.sources_checked}</summary>{quest.sources.map(key=>{const s=assignmentData.sources[key as keyof typeof assignmentData.sources];return <a key={key} href={s.url} target="_blank" rel="noopener noreferrer">{s.label} ↗</a>;})}<p>The exercises are Sae-authored from Steven’s assignment list. Software steps can change; use the exact official domain, not an ad or look-alike installer.</p></details>
 </div><div className="hw-discovery"><span className="hw-kicker">YOUR DISCOVERY LOG</span><h3>What did you find?</h3><p>Kept in the same field log as your other Anewgam notes.</p><label>What did you try?<textarea aria-label="What did you try?" maxLength={1800} rows={3} value={evidence.attempt} onChange={e=>update({attempt:e.target.value})} disabled={busy} placeholder="One small experiment, or the exact point where you got stuck."/></label><label>What happened? Show the proof.<textarea aria-label="What happened? Show the proof." maxLength={1800} rows={4} value={evidence.observation} onChange={e=>update({observation:e.target.value})} disabled={busy} placeholder="A result, sanitized output, file name, or an explanation in your own words. No secrets."/></label><label>What is the next puzzle?<textarea aria-label="What is the next puzzle?" maxLength={1800} rows={2} value={evidence.next} onChange={e=>update({next:e.target.value})} disabled={busy} placeholder="What remains unclear, or what would you try next?"/></label>
 <fieldset className="hw-check" disabled={busy}><legend>Check your understanding</legend><p>{quest.check.question}</p>{quest.check.choices.map((choice,i)=><label key={i}><input type="radio" name={'answer-'+quest.id} checked={evidence.answer===i} onChange={()=>{update({answer:i});setFeedback(i===quest!.check.answer?quest!.check.explanation:'Not quite. Revisit the clue and try again.');}}/>{choice}</label>)}{feedback&&<p role="status" className="hw-feedback">{feedback}</p>}</fieldset>
 <div className="hw-save-actions"><button type="button" className="hw-action secondary" disabled={!ready||busy} onClick={()=>keep('started')}>Save discovery</button><button type="button" className="hw-text-action" disabled={!ready||busy} onClick={()=>keep('blocked')}>Keep this blocker</button><button type="button" className="hw-action" disabled={!ready||busy||('source_hold' in quest&&!!quest.source_hold)} onClick={()=>keep('ready')}>Ready to show Steven</button></div>
 <small>“Ready” is your report, not a teacher’s approval. It is saved here, not submitted. Account creation, installation and recordings happen outside this app.</small>{progress[id]&&<details className="hw-hint"><summary>Last saved discovery receipt</summary><code>{progress[id].entry.hash}</code><p>{stateLabel[progress[id].value.status]} · {new Date(progress[id].entry.created_at).toLocaleString()}</p><a href="#log">See the saved record ↗</a></details>}
 </div></div></section>}
 {notice&&<p className="hw-notice" role="status">{notice}</p>}
 <div className="hw-privacy"><b>Assignments from Steven. Your progress stays with this browser.</b><p>No deadline has been invented. No account is pre-created or tool installed. These notes are unencrypted and not synchronized; anyone using this browser profile may read them. Don’t enter passwords, API keys, wallet recovery phrases or private account screenshots. Copy a check-in when you choose to share it—Steven does not receive it automatically.</p><a href="/goober/receipts/homework.json">Assignment and build trail ◇</a></div>
 </section>;
}

