import { createFileRoute } from '@tanstack/react-router';
import { useEffect, useRef, useState } from 'react';
import type { ChangeEvent, FormEvent } from 'react';
import { append, canonical, clear, digest, download, envelope, importLog, load, ROOT, verify } from '../lib/saedow';
import type { Draft, Entry, Kind, State } from '../lib/saedow';
import { chapter, roles, validApproach } from '../lib/story';
import art from '../lib/art.json';
import {Homework} from '../hw/Homework';
import {displayEntryBody} from '../hw/hw-core';
import {SetupGuide} from '../components/SetupGuide';
import {TakeThree} from '../components/TakeThree';
import {BoostRun} from '../anewgam/BoostRun';
import {Dialog} from '../anewgam/Dialogs';
export const Route=createFileRoute('/')({component:Home});
type View='world'|'hw'|'log'|'sources'|'install'|'setup';
type InstallEvent=Event & {prompt:()=>Promise<void>;userChoice:Promise<{outcome:string}>};
const tabs=[['world','◎','Your world'],['hw','✦','HW'],['log','≋','Field log'],['sources','◇','Sources'],['install','↙','Install'],['setup','⌁','Your PC']] as const;
const blank:Draft={kind:'note',state:'explored',title:'',body:'',why:'',next_proof:'',source:'typed-here'};
function Home(){
 const [view,setView]=useState<View>('world'),[entries,setEntries]=useState<Entry[]>([]),[ready,setReady]=useState(false),[busy,setBusy]=useState(false),[status,setStatus]=useState(''),[draft,setDraft]=useState<Draft>(blank),[query,setQuery]=useState(''),[install,setInstall]=useState<InstallEvent|null>(null),[installed,setInstalled]=useState(false),[online,setOnline]=useState(true),[receiptStatus,setReceiptStatus]=useState(''),[offline,setOffline]=useState(false);
 const importRef=useRef<HTMLInputElement>(null);
 const [runOpen,setRunOpen]=useState(false);
 const chosen=entries.filter(e=>e.source==='anewgam:approach').at(-1)?.body??'outrider';const role=validApproach(chosen)?chosen:'outrider';
 const progress=new Set(entries.filter(e=>/^anewgam:crossing:[012]$/.test(e.source)).map(e=>e.source)).size;
 const scene=chapter(Math.min(progress,2),role);
 useEffect(()=>{
  let alive=true;
  const location=()=>{const candidate=window.location.hash.slice(1);setView(candidate==='hw'||candidate.startsWith('hw/')?'hw':tabs.some(x=>x[0]===candidate)?candidate as View:'world');};location();window.addEventListener('hashchange',location);
  const network=()=>setOnline(navigator.onLine);network();window.addEventListener('online',network);window.addEventListener('offline',network);
  const capture=(event:Event)=>{event.preventDefault();setInstall(event as InstallEvent);};window.addEventListener('beforeinstallprompt',capture);
  const done=()=>{setInstalled(true);setInstall(null);};window.addEventListener('appinstalled',done);setInstalled(window.matchMedia('(display-mode: standalone)').matches||(navigator as Navigator & {standalone?:boolean}).standalone===true);
  load().then(verify).then(data=>{if(alive){setEntries(data);setReady(true);}}).catch(()=>{if(alive)setStatus('Your saved log could not be opened or verified. No entries have been replaced.');});
  if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{if(alive)setOffline(true);}).catch(()=>{if(alive)setOffline(false);});
  return()=>{alive=false;window.removeEventListener('hashchange',location);window.removeEventListener('online',network);window.removeEventListener('offline',network);window.removeEventListener('beforeinstallprompt',capture);window.removeEventListener('appinstalled',done);};
 },[]);
 async function save(value:Draft){if(!ready||busy)return;setBusy(true);setStatus('');try{setEntries(await append(value));setStatus(value.kind==='request'?'Kept on this device. This request has not been sent.':'Saved on this device.');return true;}catch(e){setStatus(e instanceof Error?e.message:'Could not save.');return false;}finally{setBusy(false);}}
 async function submit(e:FormEvent){e.preventDefault();if(await save(draft))setDraft(blank);}
 async function pick(id:string){await save({...blank,title:'Approach: '+(roles.find(r=>r.id===id)?.name??id),body:id,source:'anewgam:approach',kind:'idea',state:'candidate'});}
 async function advance(){await save({...blank,title:scene.title,body:scene.result,kind:'quest',source:'anewgam:crossing:'+progress,why:'A fictional step in this device-local opening.',next_proof:progress===2?'Return to the field log.':'Continue the next crossing step.'});}
 function prepare(title:string,kind:Kind,body='',next=''){setDraft({...blank,title,kind,body,next_proof:next,state:'candidate'});window.location.hash='log';setStatus('Draft ready. Edit it before saving.');}
 async function importFile(e:ChangeEvent<HTMLInputElement>){const file=e.target.files?.[0];if(!file)return;setBusy(true);try{if(file.size>12_000_000)throw Error('File exceeds the 12 MB limit.');setEntries(await importLog(await file.text()));setReady(true);setStatus('Imported and verified. The log stays on this device.');}catch(err){setStatus(err instanceof Error?err.message:'Import failed.');}finally{setBusy(false);e.target.value='';}}
 async function checkSources(){setReceiptStatus('Checking original bytes, display images, and trail…');try{
  for(const item of art){for(const [path,expected] of [[item.original,item.original_sha256],[item.display,item.display_sha256]]){const response=await fetch(path,{cache:'no-store'});if(!response.ok||await digest(await response.arrayBuffer())!==expected)throw Error('Asset mismatch: '+item.title);}}
  const r=await fetch('/receipts/trail.json',{cache:'no-store'});if(!r.ok)throw Error('Trail is unavailable.');const trail=await r.json();let previous=ROOT;
  for(const event of trail.events){const {hash,...unsigned}=event;if(event.previous!==previous||hash!==await digest(canonical(unsigned)))throw Error('Trail integrity mismatch.');previous=hash;}
  setReceiptStatus('Verified: 3 originals, 3 display images, and '+trail.events.length+' linked trail records. Integrity checked; authorship and live Skein acceptance are not implied.');
 }catch(err){setReceiptStatus(err instanceof Error?err.message:'Could not verify. Try again online.');}}
 async function askInstall(){if(install){try{await install.prompt();const choice=await install.userChoice;setStatus(choice.outcome==='accepted'?'Install request accepted by the browser.':'No installation was made.');setInstall(null);}catch{setStatus('Use your browser menu to install.');}}else{window.location.hash='install';}}
 async function remove(){if(!window.confirm('Delete this device’s field log and story progress? Export first to keep a copy.'))return;setBusy(true);try{await clear(entries.at(-1)?.hash??ROOT);setEntries([]);setStatus('This device’s log was deleted. Exported files were not changed.');}catch(e){setStatus(e instanceof Error?e.message:'Could not clear the log.');}finally{setBusy(false);}}
 const visible=entries.filter(e=>(e.title+' '+e.body+' '+e.kind).toLowerCase().includes(query.toLowerCase())).slice().reverse();
 return <div className="anew-shell"><a href="#main" className="skip">Skip to content</a>
  <aside className="rail"><a className="wordmark" href="#world"><img src="/assets/icon-192.png" width="38" height="38" alt=""/><span>anewgam<small>A place to return to.</small></span></a><div className="rail-label">GOOBER’S CORNER</div><nav aria-label="Main navigation">{tabs.map(([id,icon,label])=><a key={id} href={'#'+id} aria-current={view===id?'page':undefined}><span aria-hidden="true">{icon}</span>{label}</a>)}</nav><div className="rail-bottom"><span className="signal"/> {online?'Here, with you.':'Offline. Still here.'}<p>One world. Your own way through.</p><small>Saelion · First crossing</small></div></aside>
  <main id="main" tabIndex={-1}><header className="top"><span>SAE <span className="top-slash">/</span> GOOBER</span><span className="local-chip">{ready?'DEVICE-LOCAL':'OPENING…'}</span><button className="install-small" onClick={askInstall}>{installed?'Installed ✓':'Get the app ↗'}</button></header>{status&&<div className="notice" role="status">{status}<button aria-label="Dismiss notice" onClick={()=>setStatus('')}>×</button></div>}
   {view==='world'&&<><section className="hero"><img className="hero-art" src="/assets/crossing.webp" alt="A violet lantern glowing between travelers in overgrown stone ruins" fetchPriority="high"/><div className="hero-shade"/><div className="hero-copy"><div className="eyebrow">THE CROSSING · CHAPTER 01</div><h1>Find your line.<br/><em>Make it yours.</em></h1><p>A world to explore. A place to keep the good stuff.<br className="wide-only"/> Something worth coming back to.</p><a className="enter" href="#chapter">{progress===3?'Your first crossing':'Enter the Crossing'} <span>↗</span></a></div><a className="art-credit" href="#sources">Recovered art · View its trail ◇</a></section>
    <div className="welcome"><div><span className="eyebrow">GOOD TO HAVE YOU HERE, GOOBER.</span><h2>Not another feed.<br/>Your next good run.</h2></div><p>Bring the clutch moment, the half-built idea, the thing you want to figure out. Start with a little adventure. Keep whatever matters.</p></div>
    <section className="approaches" aria-labelledby="approach-title"><div className="section-heading"><h2 id="approach-title">How do you cross?</h2><span>An approach, not a label.</span></div><div className="role-grid">{roles.map(r=><button key={r.id} className={'role-card '+(role===r.id?'chosen':'')} onClick={()=>pick(r.id)} disabled={!ready||busy} aria-pressed={role===r.id}><span className="role-symbol">{r.symbol}</span><span className="role-name">{r.name}</span><strong>{r.line}</strong><span className="role-detail">{r.detail}</span><span className="role-select">{role===r.id?'Your approach ✓':'Try this approach ↗'}</span></button>)}</div><p className="fine">New possibilities alongside Princess and Knight. Change your approach any time. Roles never grant account or device access.</p></section>
    <section className="chapter" id="chapter" aria-labelledby="chapter-title"><img src={'/assets/'+(progress===3?'garden':scene.image)+'.webp'} alt="The Crossing and the garden beyond" loading="lazy"/><div className="chapter-copy"><span className="eyebrow">{progress===3?'FIRST CROSSING COMPLETE':'YOUR STRAND · '+(progress+1)+' / 3'}</span><h2 id="chapter-title">{progress===3?'A light left on.':scene.title}</h2><p>{progress===3?'You brought the relay home. Your route and the steps you took are kept in your field log. The next chapter has room for something of your own.':scene.text}</p>{progress<3?<button className="chapter-action" onClick={advance} disabled={busy||!ready}>{scene.action} <span>→</span></button>:<a className="chapter-action" href="#log">Open your field log →</a>}<small>Playable opening · Device-local fiction, not shared-world canon.</small></div></section>
    <section className="signal-challenge"><div><span className="eyebrow">KEEP THE CROSSING LIT</span><h2>A little momentum goes a long way.</h2><p>Collect the signals. Find a cleaner line. A 45-second run, kept in this world’s field log.</p></div><button onClick={()=>setRunOpen(true)} disabled={!ready}>Play Signal Run ↗</button></section><TakeThree/><section className="quick-section"><div className="section-heading"><h2>Bring something with you.</h2><span>From your game. From your day.</span></div><div className="quick-grid"><button onClick={()=>prepare('Rocket League · next good run','practice','What clicked? What is one thing to sharpen?','Name one thing to try next session.')}><span>01 / THE ARENA</span><h3>Keep the good play.</h3><p>Rocket League, Fortnite, Rust. A moment, a lesson, a clip link.</p><b>Make a field note ↗</b></button><button onClick={()=>prepare('A thing worth building','idea','','What is the smallest useful version?')}><span>02 / THE WORKSHOP</span><h3>Build your next thing.</h3><p>A base idea. A setup tweak. Something that started with “what about…”</p><b>Catch an idea ↗</b></button><button onClick={()=>prepare('Garage · next step','request','What needs attention?','Write one question or arrange one next step.')}><span>03 / THE GARAGE</span><h3>Make real life lighter.</h3><p>Keep a practical loose end somewhere it will not get lost.</p><b>Start a local draft ↗</b></button></div></section><section className="closing"><span>✧</span><p>You don’t have to arrive with a quest.<br/><strong>Showing up is a good start.</strong></p><a href="#log">Leave something for later →</a></section></>}
   {view==='hw'&&<Homework entries={entries} onKeep={save} ready={ready&&!busy}/>}
   {view==='setup'&&<SetupGuide entries={entries} onKeep={save} busy={busy||!ready}/>}
   {view==='log'&&<section className="page"><span className="eyebrow">SAEDOW · REMEMBER ENOUGH TO CONTINUE</span><h1>Your field log.</h1><p className="intro">The thought, the reason it matters, and one way forward. Nothing is sent just because you write it down.</p><div className="privacy-note"><b>Kept in this browser profile only.</b> Not cloud-synced or encrypted. Anyone using this profile may be able to read it. Export before switching devices or clearing browser data.</div>
    <div className="log-layout"><form className="entry-form" onSubmit={submit}><h2>Keep something.</h2><label>Title<input required maxLength={600} value={draft.title} onChange={e=>setDraft({...draft,title:e.target.value})} placeholder="That idea you almost forgot"/></label><div className="form-row"><label>Kind<select value={draft.kind} onChange={e=>setDraft({...draft,kind:e.target.value as Kind})}>{['note','idea','practice','quest','request'].map(k=><option key={k}>{k}</option>)}</select></label><label>State<select value={draft.state} onChange={e=>setDraft({...draft,state:e.target.value as State})}>{['imagined','explored','candidate','completed','superseded'].map(k=><option key={k}>{k}</option>)}</select></label></div><label>The thing<textarea rows={4} maxLength={8000} value={draft.body} onChange={e=>setDraft({...draft,body:e.target.value})} placeholder="A thought, a clip link, a question, a small win…"/></label><label>Why it matters<input maxLength={600} value={draft.why} onChange={e=>setDraft({...draft,why:e.target.value})}/></label><label>Smallest next proof<input maxLength={600} value={draft.next_proof} onChange={e=>setDraft({...draft,next_proof:e.target.value})} placeholder="One thing that would move this forward"/></label><button className="save-entry" disabled={!ready||busy}>{busy?'Saving…':'Keep it here'} <span>↓</span></button><small>“Completed” is your report, not machine verification. Requests remain drafts; Saedo dispatch is not connected.</small></form>
    <div className="entries"><div className="section-heading"><h2>{entries.length} kept</h2><button className="text-action" disabled={!ready||busy} onClick={()=>download('anewgam-field-log.json',envelope(entries))}>Export ↗</button></div><label className="search-label">Search your log<input type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Find a thought…"/></label>{visible.length===0?<div className="empty-state"><span>≋</span><h3>Room for a first page.</h3><p>{query?'No entries match this search.':'A good run, a wild idea, an unfinished question. Keep one.'}</p></div>:visible.map(e=><article className="entry" key={e.id}><div className="entry-meta">{e.kind} / {e.state}<time dateTime={e.created_at}>{new Date(e.created_at).toLocaleDateString()}</time></div><h3>{e.title}</h3><p>{displayEntryBody(e)}</p>{e.why&&<p className="entry-secondary"><b>Why</b> {e.why}</p>}{e.next_proof&&<p className="entry-secondary"><b>Next</b> {e.next_proof}</p>}<details><summary>Entry receipt</summary><code>{e.hash}</code><small>Source: {e.source}<br/>Scope: device-local · Authority: none</small></details></article>)}</div></div>
    <details className="management"><summary>Import, verify, or clear this device’s log</summary><p>Exports contain your notes in plain text. Import requires an empty log and verifies every linked entry. Hashes detect edits relative to the chain; they do not authenticate a person.</p><div className="actions"><button onClick={()=>importRef.current?.click()} disabled={busy||entries.length>0}>Import a verified log</button><button onClick={async()=>{try{await verify(entries);setStatus('All '+entries.length+' entry hashes match. No identity or authority is implied.');}catch(e){setStatus(String(e));}}}>Verify entries</button><button className="danger" onClick={remove} disabled={!ready||busy}>Clear this device’s log</button></div><input type="file" accept="application/json,.json" ref={importRef} onChange={importFile} hidden/></details></section>}
   {view==='sources'&&<section className="page sources"><span className="eyebrow">THE SKEIN TRAIL · SOURCE PACKET</span><h1>Nothing from nowhere.</h1><p className="intro">Old art, new possibilities, and a trail you can follow. Original files are preserved; crops and compression are recorded separately.</p><div className="receipt-banner"><div><h2>Receipts, not just a “done.”</h2><p>This is a portable, hash-linked build trail. Live Skein ingestion and acceptance have not been performed.</p></div><button onClick={checkSources}>Verify this trail ◇</button></div>{receiptStatus&&<p className="verify-result" role="status">{receiptStatus}</p>}
    <div className="source-grid">{art.map(a=><article className="source-card" key={a.id}><a href={a.original} target="_blank" rel="noreferrer"><img src={a.display} alt={a.title} loading="lazy"/></a><div><span className="source-kind">RECOVERED / LIBRARY ART</span><h2>{a.title}</h2><p>{a.generation}. This is concept artwork, not proof of a running game.</p><div className="source-actions"><a href={a.original} target="_blank" rel="noreferrer">View original ↗</a><a href={a.display} target="_blank" rel="noreferrer">Display version ↗</a></div><details><summary>Source & transformation receipt</summary><code>{a.file_id}</code><p>Original SHA-256</p><code>{a.original_sha256}</code><p>Display SHA-256</p><code>{a.display_sha256}</code><small>{a.transformation.method}. Crop: {a.transformation.crop_xyxy.join(', ')}.</small></details></div></article>)}</div>
    <div className="proof-grid"><article><span className="tag">NEW FICTION / CANDIDATE</span><h2>Three new ways through.</h2><p>Outrider, Artificer, and Wayfinder are proposed story approaches created for this opening. They do not rename earlier roles or define a real person.</p></article><article><span className="tag amber">REPORTED / NOT RECOVERED</span><h2>The earlier films.</h2><p>A supplied Crossing board mentions Protect the Lantern, GO Launch Activation, and True Faith Connection. The actual video files and scene manifest were not recovered in the Library searches. No playable video is claimed here.</p></article><article><span className="tag">CONNECTED / NOT CONNECTED</span><h2>What this doorway does.</h2><p>Art, branching opening, local log, export/import, installation help, and source verification. No AI chat, account linking, device control, messaging, or live Skein acceptance.</p></article></div><div className="receipt-downloads"><a href="/receipts/trail.json" download>Build trail · JSON ↗</a><a href="/assets/asset-provenance.json" download>Art manifest · JSON ↗</a><a href="/receipts/saedow.schema.json" download>Reusable SaeDow schema ↗</a><a href="/receipts/README.md">Build notes & known limits ↗</a><a href="/receipts/take3-video.json">Take 3 video receipt ↗</a><a href="/receipts/take3-verification.json">Take 3 and setup tests ↗</a><a href="/#setup">PC preparation guide ↗</a><a href="/receipts/main-verification.json">Main app test results ↗</a><a href="/receipts/generic-verification.json">Generic app test results ↗</a></div></section>}
   {view==='install'&&<section className="page install-page"><span className="eyebrow">A SHORTER WAY BACK</span><h1>Your world.<br/>One tap away.</h1><p className="intro">Put Anewgam beside the apps you actually use. Same doorway, less friction.</p><div className="install-panel"><img src="/assets/icon-192.png" width="96" height="96" alt="Anewgam app icon"/><div><h2>Anewgam · Goober</h2><p>{installed?'Running as an installed app.':install?'Your browser is offering installation.':'Use the steps below for your device.'}</p><button className="install-now" onClick={askInstall} disabled={installed||!install}>{installed?'Installed ✓':install?'Install Anewgam':'Browser-menu install'}</button></div></div><div className="install-grid"><article><span>01 / iPHONE</span><h2>Keep it on your Home Screen.</h2><ol><li>Open this site in Safari.</li><li>Tap Share, or More then Share.</li><li>Choose Add to Home Screen.</li><li>Turn on Open as Web App when offered, then tap Add.</li></ol><a href="https://support.apple.com/guide/iphone/open-as-web-app-iphea86e5236/ios" target="_blank" rel="noreferrer">Apple’s instructions ↗</a></article><article><span>02 / WINDOWS</span><h2>Give it its own window.</h2><ol><li>Open this site in Microsoft Edge.</li><li>Use the install icon in the address bar when it appears.</li><li>Or open the menu, then Apps, then install this site as an app.</li><li>Pin it where you will see it.</li></ol><a href="https://learn.microsoft.com/en-us/microsoft-edge/progressive-web-apps/how-to/" target="_blank" rel="noreferrer">Microsoft’s PWA guide ↗</a></article></div><div className="privacy-note"><b>{offline?'Offline shell registered.':'Offline shell not yet ready.'}</b> Load the pages once while online before relying on offline use. Each browser profile has its own field log. Installing does not connect your accounts, sync notes, or authorize remote access.</div><div className="install-foot"><h2>Desktop and phone, without pretending.</h2><p>This release does not pair devices. The desktop can be your big-screen doorway and the phone your pocket notebook, but their notes stay separate until you deliberately export and import. TV control and household access come later, through explicit enrollment.</p></div></section>}
   <footer><span>anewgam <i>·</i> with Saelion · <a href="/saedow/">Open generic SaeDow ↗</a></span><a href="#sources">Leave a trail. Keep a light on. ◇</a></footer></main>{runOpen&&<Dialog title="Signal Run · The Crossing" onClose={()=>setRunOpen(false)}><BoostRun onComplete={async(score)=>{await save({...blank,kind:"practice",state:"completed",title:"Signal Run · "+score+" signals",body:"A completed local 45-second momentum run. Score is a local report, not a verified competitive result.",why:"Keep a small piece of play in the same field log.",next_proof:"Try a cleaner line next time.",source:"anewgam:signal-run"});}}/></Dialog>}<nav className="mobile-dock" aria-label="Mobile navigation">{tabs.map(([id,icon,label])=><a key={id} href={'#'+id} aria-current={view===id?'page':undefined}><span aria-hidden="true">{icon}</span><small>{id==='world'?'World':label}</small></a>)}</nav></div>;
}

