      "url": "https://agenc.ag/core"
    },
    "chrome": {
      "label": "Chrome: manage extensions",
      "url": "https://support.google.com/chrome/answer/2664769"
    },
    "crypto-risk": {
      "label": "Investor.gov: crypto risks",
      "url": "https://www.investor.gov/introduction-investing/general-resources/news-alerts/alerts-bulletins/investor-alerts/crypto-asset-securities"
    },
    "wallet-safety": {
      "label": "Ethereum: security and scams",
      "url": "https://ethereum.org/en/security/"
    }
  },
  "quests": [
    {
      "id": "ai-prep",
      "title": "Make a safe launch pad",
      "zone": "AI prep",
      "device": "Phone + PC",
      "minutes": 15,
      "ability": "Ask better questions",
      "puzzle": "Can you tell an answer from evidence, and a helpful tool from something that needs permission?",
      "steps": [
        "Create or choose one practice folder on your PC. Keep your game saves, documents, passwords and wallets outside it. On phone, start with a note describing the practice project.",
        "Pick a tiny goal: change a game score, record a clip, or explain one piece of code. Write what would count as success before asking an AI.",
        "Ask an available AI for a plan, then name one claim you would check yourself. If you have no account yet, do the Claude quest next."
      ],
      "hints": [
