/** Native HW-tab build: existing Goober React component, mounted at the same origin. */
import * as esbuild from 'esbuild';
import {readFile,writeFile} from 'node:fs/promises';
import {resolve,extname} from 'node:path';
const ROOT=resolve('src');
await writeFile('entry.tsx',"import {createRoot} from 'react-dom/client';import {Home} from './src/routes/index';createRoot(document.getElementById('app')!).render(<Home/>);\n");
await esbuild.build({entryPoints:['entry.tsx'],outfile:'../site/goober/app.js',bundle:true,format:'esm',platform:'browser',target:'es2022',minify:true,jsx:'automatic',define:{'process.env.NODE_ENV':'"production"'},plugins:[{name:'existing-goober-mount',setup(build){build.onLoad({filter:/\.(tsx?|json)$/},async args=>{if(!args.path.startsWith(ROOT+'/'))return;let s=await readFile(args.path,'utf8');if(args.path.endsWith('/routes/index.tsx'))s=s.replace("import { createFileRoute } from '@tanstack/react-router';\n",'').replace("export const Route=createFileRoute('/')({component:Home});\n",'').replace('function Home(){','export function Home(){');
 if(args.path.endsWith('/lib/art.json')){const images=JSON.parse(s);for(const image of images){image.original='/goober'+image.original;image.display='/goober'+image.display;}s=JSON.stringify(images);}else s=s.replace(/(["'])\/(assets\/|receipts\/|saedow\/|sw\.js|manifest\.webmanifest|relay\.json|#setup)/g,(_,q,path)=>q+'/goober/'+path).replaceAll('href="/"','href="/goober/"');
 return {contents:s,loader:extname(args.path).slice(1)};});}}]});
await esbuild.build({entryPoints:['src/hw/hw-core.ts'],outfile:'hw-core.test.mjs',bundle:true,format:'esm',platform:'node',target:'es2022'});
console.log('Built native HW tab using the existing Goober store and route component.');

