/* HW: a native tab of the existing Anewgam, not a separate tracker. */
.hw{padding:20px 0 35px}.hw button,.hw a{touch-action:manipulation}.hw-kicker{font-size:9px;letter-spacing:1.7px;font-weight:600;color:#f0ce99}.hw-hero{position:relative;min-height:390px;border-radius:16px;overflow:hidden;border:1px solid #75538b;background:#281637;display:flex;align-items:center;justify-content:space-between;gap:25px}.hw-hero>img,.hw-hero-veil{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center 38%}.hw-hero-veil{background:linear-gradient(90deg,#180d2bf2,#251438c9 55%,#26103751),linear-gradient(0deg,#150b2590,transparent)}.hw-hero-copy{position:relative;padding:35px 40px;max-width:580px}.hw-hero h1{font:64px/1.03 Georgia,serif;letter-spacing:-2px;margin:19px 0}.hw-hero h1 em{font-weight:normal;color:#e9bffe}.hw-hero p{font-size:14px;line-height:1.8;color:#e0cfeb;max-width:390px}.hw-start{display:inline-flex;justify-content:space-between;align-items:center;gap:28px;min-height:47px;padding:11px 20px;border-radius:27px;background:#edcc98;color:#2b1c32;font-size:12px;font-weight:650;margin-top:25px}.hw-start span{font-size:21px}.hw-hero-stat{position:relative;align-self:flex-end;flex-shrink:0;margin:0 28px 28px;padding:18px 20px;background:#1b1121bb;border:1px solid #a47fb966;backdrop-filter:blur(10px);border-radius:12px}.hw-hero-stat strong{display:block;font:49px/1 Georgia,serif;color:#ffe4b8}.hw-hero-stat strong small{font:20px Georgia,serif;color:#d3bddd}.hw-hero-stat>span{display:block;font-size:10px;color:#d7c2df;line-height:1.65;margin-top:10px}.hw-loop{display:flex;align-items:center;gap:20px;padding:22px 2px 27px;border-bottom:1px solid #44344f;margin-bottom:30px;flex-wrap:wrap}.hw-loop>span{font-size:8px;letter-spacing:1.5px;color:#d5acd8}.hw-loop p{color:#bcabc9;font-size:12px;letter-spacing:.3px}.hw-loop b{color:#edca99;font-weight:500}.hw-loop small{font-size:10px;color:#b8a3c8;margin-left:auto}.hw-section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin:25px 0}.hw-section